import{_ as n,c as s,o as t,ag as e}from"./chunks/framework.CMajxlqO.js";const u=JSON.parse('{"title":"Programmeringsspråk: LAD, FBD, SCL","description":"","frontmatter":{},"headers":[],"relativePath":"04-programmering/sprak-lad-fbd-scl.md","filePath":"04-programmering/sprak-lad-fbd-scl.md","lastUpdated":1768316137000}'),r={name:"04-programmering/sprak-lad-fbd-scl.md"};function l(o,a,i,p,d,c){return t(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="programmeringssprak-lad-fbd-scl" tabindex="-1">Programmeringsspråk: LAD, FBD, SCL <a class="header-anchor" href="#programmeringssprak-lad-fbd-scl" aria-label="Permalink to &quot;Programmeringsspråk: LAD, FBD, SCL&quot;">​</a></h1><p>TIA Portal stöder flera programmeringsspråk enligt IEC 61131-3-standarden. De tre vanligaste är <strong>LAD (Ladder Diagram)</strong>, <strong>FBD (Function Block Diagram)</strong> och <strong>SCL (Structured Control Language)</strong>. Varje språk har sina för- och nackdelar beroende på applikation och personlig preferens.</p><h2 id="lad-ladder-diagram-stegdiagram" tabindex="-1">LAD - Ladder Diagram (Stegdiagram) <a class="header-anchor" href="#lad-ladder-diagram-stegdiagram" aria-label="Permalink to &quot;LAD - Ladder Diagram (Stegdiagram)&quot;">​</a></h2><h3 id="vad-ar-lad" tabindex="-1">Vad är LAD? <a class="header-anchor" href="#vad-ar-lad" aria-label="Permalink to &quot;Vad är LAD?&quot;">​</a></h3><p>LAD är ett <strong>grafiskt språk</strong> som liknar elektriska reläscheman. Det är det mest använda PLC-språket i industrin, särskilt i USA och Asien.</p><h3 id="struktur" tabindex="-1">Struktur <a class="header-anchor" href="#struktur" aria-label="Permalink to &quot;Struktur&quot;">​</a></h3><p>LAD-kod består av:</p><ul><li><strong>Power rails</strong> (strömskenor) - Vänster och höger sida</li><li><strong>Rungs</strong> (stegar) - Horisontella rader med logik</li><li><strong>Contacts</strong> (kontakter) - Representerar villkor (NO/NC)</li><li><strong>Coils</strong> (spolar) - Representerar utgångar</li></ul><h3 id="grundlaggande-element" tabindex="-1">Grundläggande element <a class="header-anchor" href="#grundlaggande-element" aria-label="Permalink to &quot;Grundläggande element&quot;">​</a></h3><h4 id="normally-open-no-kontakt" tabindex="-1">Normally Open (NO) kontakt <a class="header-anchor" href="#normally-open-no-kontakt" aria-label="Permalink to &quot;Normally Open (NO) kontakt&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---| |---    # Stängs när variabel = TRUE</span></span></code></pre></div><h4 id="normally-closed-nc-kontakt" tabindex="-1">Normally Closed (NC) kontakt <a class="header-anchor" href="#normally-closed-nc-kontakt" aria-label="Permalink to &quot;Normally Closed (NC) kontakt&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---|/|---    # Stängs när variabel = FALSE</span></span></code></pre></div><h4 id="output-coil" tabindex="-1">Output Coil <a class="header-anchor" href="#output-coil" aria-label="Permalink to &quot;Output Coil&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---( )---    # Sätter utgång</span></span></code></pre></div><h4 id="set-reset-coils" tabindex="-1">Set/Reset Coils <a class="header-anchor" href="#set-reset-coils" aria-label="Permalink to &quot;Set/Reset Coils&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---(S)---    # Sätt (bibehålls)</span></span>
<span class="line"><span>---(R)---    # Nollställ</span></span></code></pre></div><h3 id="exempel-enkel-start-stopp-logik" tabindex="-1">Exempel: Enkel start/stopp-logik <a class="header-anchor" href="#exempel-enkel-start-stopp-logik" aria-label="Permalink to &quot;Exempel: Enkel start/stopp-logik&quot;">​</a></h3><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Network 1: Start motor</span></span>
<span class="line"><span>---| Start_Button |------| NOT Stop_Button |------( Motor_Running )---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Network 2: Motor output</span></span>
<span class="line"><span>---| Motor_Running |------( Motor_Output )---</span></span></code></pre></div><p>Oversatt till logik:</p><ul><li>Motor startar när Start_Button trycks OCH Stop_Button inte är tryckt</li><li>Motor_Output aktiveras när Motor_Running = TRUE</li></ul><h3 id="exempel-sjalvhallning-latching" tabindex="-1">Exempel: Självhållning (latching) <a class="header-anchor" href="#exempel-sjalvhallning-latching" aria-label="Permalink to &quot;Exempel: Självhållning (latching)&quot;">​</a></h3><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Network 1: Motor med självhållning</span></span>
<span class="line"><span>          Start_Button        Motor_Running      Stop_Button</span></span>
<span class="line"><span>---| |-------------||--------------| / |--------( Motor_Running )---</span></span>
<span class="line"><span>         (1)            (2)                (3)</span></span></code></pre></div><p>Logik:</p><ol><li>Start_Button aktiverar Motor_Running</li><li>Motor_Running håller sig själv aktiv (självhållning)</li><li>Stop_Button bryter kretsen</li></ol><h3 id="fordelar-med-lad" tabindex="-1">Fördelar med LAD <a class="header-anchor" href="#fordelar-med-lad" aria-label="Permalink to &quot;Fördelar med LAD&quot;">​</a></h3><p>✅ <strong>Intuitivt</strong> - Liknar elektriska scheman ✅ <strong>Visuellt</strong> - Lätt att följa signalflödet ✅ <strong>Branschstandard</strong> - Mest använt i industrin ✅ <strong>Enkel felsökning</strong> - Signal-tracing online</p><h3 id="nackdelar-med-lad" tabindex="-1">Nackdelar med LAD <a class="header-anchor" href="#nackdelar-med-lad" aria-label="Permalink to &quot;Nackdelar med LAD&quot;">​</a></h3><p>❌ <strong>Komplex matematik</strong> - Svårt att skriva beräkningar ❌ <strong>Strukturerad data</strong> - Svårt med loopar och strukturer ❌ <strong>Tar plats</strong> - Mycket skrollning för stora program</p><h2 id="fbd-function-block-diagram" tabindex="-1">FBD - Function Block Diagram <a class="header-anchor" href="#fbd-function-block-diagram" aria-label="Permalink to &quot;FBD - Function Block Diagram&quot;">​</a></h2><h3 id="vad-ar-fbd" tabindex="-1">Vad är FBD? <a class="header-anchor" href="#vad-ar-fbd" aria-label="Permalink to &quot;Vad är FBD?&quot;">​</a></h3><p>FBD är ett <strong>grafiskt språk</strong> baserat på funktionsblock. Det liknar logikdiagram och används ofta för process- och regleringssystem.</p><h3 id="struktur-1" tabindex="-1">Struktur <a class="header-anchor" href="#struktur-1" aria-label="Permalink to &quot;Struktur&quot;">​</a></h3><p>FBD består av:</p><ul><li><strong>Funktionsblock</strong> - Rutor som representerar funktioner</li><li><strong>Ingångar</strong> - Till vänster på blocket</li><li><strong>Utgångar</strong> - Till höger på blocket</li><li><strong>Kopplingar</strong> - Linjer som förbinder block</li></ul><h3 id="grundlaggande-funktionsblock" tabindex="-1">Grundläggande funktionsblock <a class="header-anchor" href="#grundlaggande-funktionsblock" aria-label="Permalink to &quot;Grundläggande funktionsblock&quot;">​</a></h3><h4 id="and-block" tabindex="-1">AND-block <a class="header-anchor" href="#and-block" aria-label="Permalink to &quot;AND-block&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Input1  ┌─────┐</span></span>
<span class="line"><span>─────────┤ AND ├───── Output</span></span>
<span class="line"><span>  Input2  └─────┘</span></span></code></pre></div><h4 id="or-block" tabindex="-1">OR-block <a class="header-anchor" href="#or-block" aria-label="Permalink to &quot;OR-block&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Input1  ┌────┐</span></span>
<span class="line"><span>─────────┤ OR ├───── Output</span></span>
<span class="line"><span>  Input2  └────┘</span></span></code></pre></div><h4 id="not-block-inverterare" tabindex="-1">NOT-block (inverterare) <a class="header-anchor" href="#not-block-inverterare" aria-label="Permalink to &quot;NOT-block (inverterare)&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Input   ┌─────┐</span></span>
<span class="line"><span>─────────┤ NOT ├───── Output</span></span>
<span class="line"><span>          └─────┘</span></span></code></pre></div><h3 id="exempel-timer-med-and-logik" tabindex="-1">Exempel: Timer med AND-logik <a class="header-anchor" href="#exempel-timer-med-and-logik" aria-label="Permalink to &quot;Exempel: Timer med AND-logik&quot;">​</a></h3><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Start_Button ┌─────┐     ┌──────────┐</span></span>
<span class="line"><span>────────────┤ AND ├─────┤ IN   TON ├─── Motor_Running</span></span>
<span class="line"><span>  Emergency  └─────┘     │  PT=5s  │</span></span>
<span class="line"><span>  (NOT)                  └──────────┘</span></span></code></pre></div><p>Logik: Motor startar om Start_Button = TRUE OCH Emergency = FALSE, fördröjning 5 sekunder.</p><h3 id="fordelar-med-fbd" tabindex="-1">Fördelar med FBD <a class="header-anchor" href="#fordelar-med-fbd" aria-label="Permalink to &quot;Fördelar med FBD&quot;">​</a></h3><p>✅ <strong>Tydligt signalflöde</strong> - Vänster till höger ✅ <strong>Bra för matematik</strong> - Enklare än LAD ✅ <strong>Funktionsblock</strong> - Inbyggda funktioner (timers, counters, PID) ✅ <strong>Processindustri</strong> - Vanligt i reglersystem</p><h3 id="nackdelar-med-fbd" tabindex="-1">Nackdelar med FBD <a class="header-anchor" href="#nackdelar-med-fbd" aria-label="Permalink to &quot;Nackdelar med FBD&quot;">​</a></h3><p>❌ <strong>Mindre intuitivt</strong> - Kräver mer träning än LAD ❌ <strong>Komplex layout</strong> - Kan bli rörigt vid stora program ❌ <strong>Mindre använt</strong> - Inte lika populärt som LAD/SCL</p><h2 id="scl-structured-control-language" tabindex="-1">SCL - Structured Control Language <a class="header-anchor" href="#scl-structured-control-language" aria-label="Permalink to &quot;SCL - Structured Control Language&quot;">​</a></h2><h3 id="vad-ar-scl" tabindex="-1">Vad är SCL? <a class="header-anchor" href="#vad-ar-scl" aria-label="Permalink to &quot;Vad är SCL?&quot;">​</a></h3><p>SCL är ett <strong>textbaserat språk</strong> liknande Pascal/C. Det är kraftfullt för komplexa beräkningar, datahantering och strukturerad programmering.</p><h3 id="struktur-2" tabindex="-1">Struktur <a class="header-anchor" href="#struktur-2" aria-label="Permalink to &quot;Struktur&quot;">​</a></h3><p>SCL använder standard programmeringsstrukturer:</p><ul><li><strong>IF-THEN-ELSE</strong> - Villkorssatser</li><li><strong>CASE</strong> - Switchsatser</li><li><strong>FOR/WHILE</strong> - Loopar</li><li><strong>Funktionsanrop</strong> - Likt andra programmeringsspråk</li></ul><h3 id="grundlaggande-syntax" tabindex="-1">Grundläggande syntax <a class="header-anchor" href="#grundlaggande-syntax" aria-label="Permalink to &quot;Grundläggande syntax&quot;">​</a></h3><h4 id="tilldelning" tabindex="-1">Tilldelning <a class="header-anchor" href="#tilldelning" aria-label="Permalink to &quot;Tilldelning&quot;">​</a></h4><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Motor_Output := Start_Button AND NOT Stop_Button;</span></span></code></pre></div><h4 id="if-sats" tabindex="-1">IF-sats <a class="header-anchor" href="#if-sats" aria-label="Permalink to &quot;IF-sats&quot;">​</a></h4><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IF Temperature &gt; 80.0 THEN</span></span>
<span class="line"><span>    Alarm := TRUE;</span></span>
<span class="line"><span>    Cooling_Valve := TRUE;</span></span>
<span class="line"><span>ELSIF Temperature &lt; 20.0 THEN</span></span>
<span class="line"><span>    Heater := TRUE;</span></span>
<span class="line"><span>ELSE</span></span>
<span class="line"><span>    Alarm := FALSE;</span></span>
<span class="line"><span>    Cooling_Valve := FALSE;</span></span>
<span class="line"><span>    Heater := FALSE;</span></span>
<span class="line"><span>END_IF;</span></span></code></pre></div><h4 id="case-sats" tabindex="-1">CASE-sats <a class="header-anchor" href="#case-sats" aria-label="Permalink to &quot;CASE-sats&quot;">​</a></h4><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CASE Operating_Mode OF</span></span>
<span class="line"><span>    0:  // Manual mode</span></span>
<span class="line"><span>        Motor_Speed := Manual_Setpoint;</span></span>
<span class="line"><span>    1:  // Automatic mode</span></span>
<span class="line"><span>        Motor_Speed := Auto_Setpoint;</span></span>
<span class="line"><span>    2:  // Maintenance mode</span></span>
<span class="line"><span>        Motor_Speed := 0;</span></span>
<span class="line"><span>END_CASE;</span></span></code></pre></div><h4 id="for-loop" tabindex="-1">FOR-loop <a class="header-anchor" href="#for-loop" aria-label="Permalink to &quot;FOR-loop&quot;">​</a></h4><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FOR i := 0 TO 9 DO</span></span>
<span class="line"><span>    Sensor_Average := Sensor_Average + Sensor_Array[i];</span></span>
<span class="line"><span>END_FOR;</span></span>
<span class="line"><span>Sensor_Average := Sensor_Average / 10.0;</span></span></code></pre></div><h3 id="exempel-motorstyrning-med-logik" tabindex="-1">Exempel: Motorstyrning med logik <a class="header-anchor" href="#exempel-motorstyrning-med-logik" aria-label="Permalink to &quot;Exempel: Motorstyrning med logik&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Motor start-logik</span></span>
<span class="line"><span>IF Start_Button AND NOT Emergency_Stop THEN</span></span>
<span class="line"><span>    IF Temperature &lt; Max_Temp AND NOT Fault THEN</span></span>
<span class="line"><span>        Motor_Enable := TRUE;</span></span>
<span class="line"><span>        Status_LED := TRUE;</span></span>
<span class="line"><span>    ELSE</span></span>
<span class="line"><span>        Motor_Enable := FALSE;</span></span>
<span class="line"><span>        Fault_LED := TRUE;</span></span>
<span class="line"><span>    END_IF;</span></span>
<span class="line"><span>END_IF;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Stopp-logik</span></span>
<span class="line"><span>IF Stop_Button OR Emergency_Stop OR Fault THEN</span></span>
<span class="line"><span>    Motor_Enable := FALSE;</span></span>
<span class="line"><span>    Status_LED := FALSE;</span></span>
<span class="line"><span>END_IF;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Hastighetsberäkning</span></span>
<span class="line"><span>IF Motor_Enable THEN</span></span>
<span class="line"><span>    Motor_Speed := (Speed_Setpoint * 16384.0) / 100.0;  // Skala 0-100% till 0-16384</span></span>
<span class="line"><span>ELSE</span></span>
<span class="line"><span>    Motor_Speed := 0;</span></span>
<span class="line"><span>END_IF;</span></span></code></pre></div><h3 id="fordelar-med-scl" tabindex="-1">Fördelar med SCL <a class="header-anchor" href="#fordelar-med-scl" aria-label="Permalink to &quot;Fördelar med SCL&quot;">​</a></h3><p>✅ <strong>Kraftfullt</strong> - Komplex logik och beräkningar ✅ <strong>Kompakt</strong> - Mindre kod än LAD/FBD ✅ <strong>Strukturerat</strong> - Loopar, funktioner, strukturer ✅ <strong>Bekant</strong> - Liknar C/Pascal för programmerare</p><h3 id="nackdelar-med-scl" tabindex="-1">Nackdelar med SCL <a class="header-anchor" href="#nackdelar-med-scl" aria-label="Permalink to &quot;Nackdelar med SCL&quot;">​</a></h3><p>❌ <strong>Inlärningskurva</strong> - Kräver programmeringskunskap ❌ <strong>Felsökning</strong> - Svårare än LAD att följa online ❌ <strong>Mindre visuellt</strong> - Inte lika intuitivt som grafiska språk</p><h2 id="jamforelse-lad-vs-fbd-vs-scl" tabindex="-1">Jämförelse: LAD vs FBD vs SCL <a class="header-anchor" href="#jamforelse-lad-vs-fbd-vs-scl" aria-label="Permalink to &quot;Jämförelse: LAD vs FBD vs SCL&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspekt</th><th>LAD</th><th>FBD</th><th>SCL</th></tr></thead><tbody><tr><td><strong>Typ</strong></td><td>Grafiskt</td><td>Grafiskt</td><td>Text</td></tr><tr><td><strong>Inlärningskurva</strong></td><td>Låg</td><td>Medel</td><td>Hög</td></tr><tr><td><strong>Matematik</strong></td><td>Svårt</td><td>Medel</td><td>Enkelt</td></tr><tr><td><strong>Loopar</strong></td><td>Nej</td><td>Begränsat</td><td>Ja</td></tr><tr><td><strong>Felsökning</strong></td><td>Utmärkt</td><td>Bra</td><td>Medel</td></tr><tr><td><strong>Kodlängd</strong></td><td>Lång</td><td>Medel</td><td>Kort</td></tr><tr><td><strong>Bransch</strong></td><td>Tillverkning</td><td>Process</td><td>Avancerade system</td></tr><tr><td><strong>Hastighet</strong></td><td>Samma</td><td>Samma</td><td>Samma</td></tr></tbody></table><h2 id="nar-ska-du-anvanda-vilket-sprak" tabindex="-1">När ska du använda vilket språk? <a class="header-anchor" href="#nar-ska-du-anvanda-vilket-sprak" aria-label="Permalink to &quot;När ska du använda vilket språk?&quot;">​</a></h2><h3 id="anvand-lad-for" tabindex="-1">Använd LAD för: <a class="header-anchor" href="#anvand-lad-for" aria-label="Permalink to &quot;Använd LAD för:&quot;">​</a></h3><p>✅ Enkel logik (start/stopp, interlocks) ✅ Relay-replacement (ersätta relästyrning) ✅ När elektrikerbakgrund finns i teamet ✅ Quick troubleshooting på plats</p><h3 id="anvand-fbd-for" tabindex="-1">Använd FBD för: <a class="header-anchor" href="#anvand-fbd-for" aria-label="Permalink to &quot;Använd FBD för:&quot;">​</a></h3><p>✅ Processstyrning och reglering ✅ Tidskritiska sekvenser ✅ När signalflöde är viktigt ✅ Visualisering av logikblock</p><h3 id="anvand-scl-for" tabindex="-1">Använd SCL för: <a class="header-anchor" href="#anvand-scl-for" aria-label="Permalink to &quot;Använd SCL för:&quot;">​</a></h3><p>✅ Komplexa beräkningar (trigonometri, statistik) ✅ Datahantering (arrayer, strukturer) ✅ Algoritmer (sortering, sökning) ✅ Code reuse och bibliotek ✅ När du har programmerarbakgrund</p><h2 id="kombinera-sprak-i-samma-projekt" tabindex="-1">Kombinera språk i samma projekt <a class="header-anchor" href="#kombinera-sprak-i-samma-projekt" aria-label="Permalink to &quot;Kombinera språk i samma projekt&quot;">​</a></h2><p>TIA Portal tillåter att blanda språk:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OB1 (LAD)</span></span>
<span class="line"><span>  ├─ FB_Motor (LAD) - Enkel start/stopp</span></span>
<span class="line"><span>  ├─ FB_PID (FBD) - Reglerloop</span></span>
<span class="line"><span>  └─ FC_Calculate (SCL) - Avancerad matematik</span></span></code></pre></div><h3 id="best-practice-anvand-ratt-verktyg-for-ratt-jobb" tabindex="-1">Best practice: Använd rätt verktyg för rätt jobb <a class="header-anchor" href="#best-practice-anvand-ratt-verktyg-for-ratt-jobb" aria-label="Permalink to &quot;Best practice: Använd rätt verktyg för rätt jobb&quot;">​</a></h3><p>✅ <strong>OB1 i LAD</strong> - Huvudprogram, enkel struktur ✅ <strong>FB för maskinlogik i LAD</strong> - Intuitivt ✅ <strong>FC för matematik i SCL</strong> - Effektivt ✅ <strong>FB för PID/reglering i FBD</strong> - Tydligt</p><h2 id="praktiskt-exempel-alla-tre-spraken" tabindex="-1">Praktiskt exempel: Alla tre språken <a class="header-anchor" href="#praktiskt-exempel-alla-tre-spraken" aria-label="Permalink to &quot;Praktiskt exempel: Alla tre språken&quot;">​</a></h2><h3 id="problem-styr-motor-baserat-pa-temperatur" tabindex="-1">Problem: Styr motor baserat på temperatur <a class="header-anchor" href="#problem-styr-motor-baserat-pa-temperatur" aria-label="Permalink to &quot;Problem: Styr motor baserat på temperatur&quot;">​</a></h3><p><strong>LAD-version (OB1):</strong></p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Network 1: Temperature check</span></span>
<span class="line"><span>---| Temp &gt; 50.0 |------( Overheat_Alarm )---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Network 2: Motor control</span></span>
<span class="line"><span>---| Start_Btn |---| NOT Overheat_Alarm |---( Motor_Run )---</span></span></code></pre></div><p><strong>FBD-version:</strong></p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Temp ┌──────┐     ┌─────┐</span></span>
<span class="line"><span>─────┤ &gt;50  ├─────┤ NOT ├────┐   ┌─────┐</span></span>
<span class="line"><span>     └──────┘     └─────┘    ├───┤ AND ├─── Motor_Run</span></span>
<span class="line"><span>Start                        │   └─────┘</span></span>
<span class="line"><span>──────────────────────────────┘</span></span></code></pre></div><p><strong>SCL-version:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Temperaturövervakning</span></span>
<span class="line"><span>IF Temperature &gt; 50.0 THEN</span></span>
<span class="line"><span>    Overheat_Alarm := TRUE;</span></span>
<span class="line"><span>ELSE</span></span>
<span class="line"><span>    Overheat_Alarm := FALSE;</span></span>
<span class="line"><span>END_IF;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Motorstyrning</span></span>
<span class="line"><span>Motor_Run := Start_Button AND NOT Overheat_Alarm;</span></span></code></pre></div><p>Alla tre ger samma resultat - välj det du tycker är tydligast!</p><h2 id="resurser-och-dokumentation" tabindex="-1">Resurser och dokumentation <a class="header-anchor" href="#resurser-och-dokumentation" aria-label="Permalink to &quot;Resurser och dokumentation&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/36932465" target="_blank" rel="noreferrer">S7-1200 Programming Languages</a> - Språkreferens</li><li><a href="https://support.industry.siemens.com/cs/ww/en/view/90885040" target="_blank" rel="noreferrer">STEP 7 Programming Guideline</a> - Best practices</li><li><a href="https://support.industry.siemens.com/cs/ww/en/view/86630375" target="_blank" rel="noreferrer">Comparison List for Programming Languages</a> - Jämförelse</li></ul><h3 id="video-tutorials" tabindex="-1">Video-tutorials <a class="header-anchor" href="#video-tutorials" aria-label="Permalink to &quot;Video-tutorials&quot;">​</a></h3><ul><li>YouTube: &quot;TIA Portal LAD programming tutorial&quot;</li><li>YouTube: &quot;TIA Portal FBD programming tutorial&quot;</li><li>YouTube: &quot;TIA Portal SCL programming tutorial&quot;</li><li>YouTube: &quot;When to use LAD vs FBD vs SCL&quot;</li></ul><div class="tip custom-block"><p class="custom-block-title">Nästa steg</p><p>Nu när du förstår språken, lär dig skapa <a href="./logiska-funktioner.html">Enkla logiska funktioner</a> i praktiken!</p></div>`,99)])])}const h=n(r,[["render",l]]);export{u as __pageData,h as default};
